} else if (this.alter) {
  // Try other variations.
  this.server.closeCachedConnections();
  try {
    this.tryNextLogon(url);
  } catch (e) {
    this._log.error("Logon for alternative FAILED!", e);
    this._failed(url);
  }
} else {
  // Logon failed, and we aren't supposed to try other variations.
  this._failed(url);
}
